<?php
final class Repository {
    public function __construct(private PDO $db) {}
    public function participants(string $search='', ?bool $active=null): array { $sql='SELECT * FROM participants WHERE 1=1';$args=[];if($search!==''){$sql.=' AND (full_name LIKE ? OR document LIKE ? OR phone LIKE ?)';$q='%'.$search.'%';$args=[$q,$q,$q];}if($active!==null){$sql.=' AND active=?';$args[]=$active?1:0;}$sql.=' ORDER BY active DESC, full_name';$s=$this->db->prepare($sql);$s->execute($args);return $s->fetchAll(); }
    public function createParticipant(array $data): int { $s=$this->db->prepare('INSERT INTO participants(document,full_name,phone,email,active) VALUES(?,?,?,?,1)');$s->execute([trim($data['document']),trim($data['full_name']),trim($data['phone']??''),trim($data['email']??'')]);return (int)$this->db->lastInsertId(); }
    public function updateParticipant(int $id,array $data): void { $s=$this->db->prepare('UPDATE participants SET document=?,full_name=?,phone=?,email=? WHERE id=?');$s->execute([trim($data['document']),trim($data['full_name']),trim($data['phone']??''),trim($data['email']??''),$id]); }
    public function setParticipantActive(int $id,bool $active): void { if(!$active){$s=$this->db->prepare('SELECT id,principal,term_months FROM loans WHERE participant_id=? AND status="active" ORDER BY id');$s->execute([$id]);$loans=$s->fetchAll();if($loans){$summary=array_map(fn($l)=>'#'.(int)$l['id'].' por $'.number_format((float)$l['principal'],0,',','.').' a '.$l['term_months'].' meses',$loans);throw new RuntimeException('No se puede desactivar: tiene '.count($loans).' préstamo(s) activo(s): '.implode(', ',$summary).'.');}}$s=$this->db->prepare('UPDATE participants SET active=? WHERE id=?');$s->execute([$active?1:0,$id]); }
    public function deleteParticipant(int $id): void { $s=$this->db->prepare('SELECT COUNT(*) FROM contributions WHERE participant_id=? UNION ALL SELECT COUNT(*) FROM loans WHERE participant_id=?');$s->execute([$id,$id]);foreach($s as $row)if((int)array_values($row)[0]>0)throw new RuntimeException('No se puede eliminar un participante con historial financiero.');$s=$this->db->prepare('DELETE FROM participants WHERE id=?');$s->execute([$id]); }
    public function recordContribution(int $participant,int $year,int $month,float $amount,float $due=100000): void { $s=$this->db->prepare('SELECT amount_paid,amount_due FROM contributions WHERE participant_id=? AND year=? AND month=?');$s->execute([$participant,$year,$month]);$old=$s->fetch();$current=(float)($old['amount_paid']??0);$target=(float)($old['amount_due']??$due);if($current>=$target)throw new RuntimeException('Este mes ya está completo. Reinicia el aporte antes de registrar otro pago.');$paid=Finance::applyContribution($current,$target,(string)$amount);$s=$this->db->prepare('INSERT INTO contributions(participant_id,year,month,amount_due,amount_paid) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE amount_paid=VALUES(amount_paid)');$s->execute([$participant,$year,$month,$target,$paid]); }
    public function resetContribution(int $participant,int $year,int $month): void { $s=$this->db->prepare('UPDATE contributions SET amount_paid=0 WHERE participant_id=? AND year=? AND month=?');$s->execute([$participant,$year,$month]); }
    public function payInstallment(int $id,float $amount): void { $s=$this->db->prepare('UPDATE loan_installments SET paid_amount=LEAST(total_amount,GREATEST(0,paid_amount+?)) WHERE id=?');$s->execute([$amount,$id]);$s=$this->db->prepare('UPDATE loans l SET status="paid" WHERE l.id=(SELECT loan_id FROM loan_installments WHERE id=?) AND NOT EXISTS(SELECT 1 FROM loan_installments i WHERE i.loan_id=l.id AND i.paid_amount<i.total_amount)');$s->execute([$id]); }
    public function cancelLoan(int $id): void { $this->db->beginTransaction();try{$s=$this->db->prepare('UPDATE loans SET status="cancelled" WHERE id=? AND status<>"paid"');$s->execute([$id]);$s=$this->db->prepare('UPDATE loan_installments SET paid_amount=total_amount WHERE loan_id=?');$s->execute([$id]);$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;} }
    public function loans(string $status='',string $search=''): array { $sql='SELECT l.*,p.full_name FROM loans l JOIN participants p ON p.id=l.participant_id WHERE 1=1';$args=[];if(in_array($status,['active','paid','cancelled'],true)){$sql.=' AND l.status=?';$args[]=$status;}if($search!==''){$sql.=' AND (p.full_name LIKE ? OR p.document LIKE ?)';$q='%'.$search.'%';$args[]=$q;$args[]=$q;}$sql.=' ORDER BY l.start_date DESC';$s=$this->db->prepare($sql);$s->execute($args);return $s->fetchAll(); }
    public function annualReport(int $year): array { $participants=$this->participants('',true);$rows=[];$totalInterest=0.0;$loans=$this->loans();foreach($participants as $p){$interest=0.0;$paid=0.0;$own=0;$referred=0;foreach($loans as $l){if((int)$l['participant_id']!==(int)$p['id']||(int)substr($l['start_date'],0,4)!==$year)continue;$own+=($l['loan_type']==='PARTICIPANT'?1:0);$referred+=($l['loan_type']==='REFERRED'?1:0);$q=$this->db->prepare('SELECT * FROM loan_installments WHERE loan_id=?');$q->execute([$l['id']]);$installments=$q->fetchAll();$fully=!empty($installments)&&array_reduce($installments,fn($ok,$i)=>$ok&&(float)$i['paid_amount']>=(float)$i['total_amount'],true);if($fully){$interest+=Finance::collectedInterest($installments);$paid+=array_sum(array_column($installments,'paid_amount'));}}$s=$this->db->prepare('SELECT COALESCE(SUM(amount_paid),0) FROM contributions WHERE participant_id=? AND year=?');$s->execute([$p['id'],$year]);$rows[]=['participant'=>$p,'savings'=>(float)$s->fetchColumn(),'interest_generated'=>$interest,'total_paid'=>$paid,'own_count'=>$own,'referred_count'=>$referred];$totalInterest+=$interest;} $share=count($participants)?Finance::money($totalInterest/count($participants)):0;foreach($rows as &$row)$row['interest_share']=$share;return ['rows'=>$rows,'total_interest'=>$totalInterest,'share'=>$share]; }
}
